export const TYPE_ICON = {
  configuration: 'gear',
  controller: 'lightning',
  database: 'database',
  documentation: 'file-text',
  'external-system': 'cloud',
  policy: 'flag',
  provider: 'plugs',
  route: 'path',
  service: 'pulse',
  surface: 'browsers',
  test: 'flask',
};

/** Own-property lookup, so data such as an id of "constructor" never reaches Object.prototype. */
const own = (table, key) => (Object.hasOwn(table, key) ? table[key] : undefined);

/** Module icon overrides. Each atlas pack supplies its own via meta.nodeIcons. */
export const NODE_ICON = {};

export function resolveNodeIcon(node) {
  return node.icon ?? own(NODE_ICON, node.id) ?? own(TYPE_ICON, node.type) ?? 'cube';
}

/** Merge an atlas pack's icon map (meta.nodeIcons) into the shared lookup. */
export function registerNodeIcons(map = {}) {
  Object.entries(map).forEach(([id, icon]) => {
    if (own(PHOSPHOR, icon)) NODE_ICON[id] = icon;
  });
}

function pathsFor(iconId, weight = 'regular') {
  const table = weight === 'bold' ? PHOSPHOR_BOLD : weight === 'fill' ? PHOSPHOR_FILL : PHOSPHOR;
  return own(table, iconId) ?? own(PHOSPHOR, iconId) ?? PHOSPHOR.cube;
}

/** Inline SVG group for use inside the atlas <svg> (flat mode nodes). */
export function renderIconMarkup(iconId, { x, y, size = 11, className = 'node-glyph', weight = 'regular' } = {}) {
  const paths = pathsFor(iconId, weight);
  if (!paths?.length) return '';
  const half = size / 2;
  const body = paths.map((d) => `<path d="${d}" />`).join('');
  return `<g class="${className}" transform="translate(${x - half} ${y - half}) scale(${size / 256})" aria-hidden="true">${body}</g>`;
}

/** Standalone <svg> markup for HTML chrome and labels. */
export function iconSvg(iconId, { size = 16, weight = 'regular', className = 'ph-icon' } = {}) {
  const paths = pathsFor(iconId, weight);
  const body = paths.map((d) => `<path d="${d}" />`).join('');
  return `<svg class="${className}" width="${size}" height="${size}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true" focusable="false">${body}</svg>`;
}

export function hasIcon(iconId) {
  return Boolean(PHOSPHOR[iconId]);
}
